    $self->normalize();
    my $c = $self->{counts}{$ctx} ||= [0, 0];
    my $split = int($self->{range} * ($c->[0] + 1) / ($c->[0] + $c->[1] + 2));
    if ($bit) {
        $self->{low} += $split;
        $self->{range} -= $split;
        $c->[1]++;
    } else {
        $self->{range} = $split;
